//! Bounded fragments of the final admitted encoder; no second semantic cache.
use super::{encoded_bytes::{ByteCursor,Fragment,MAX_FRAGMENT},QueryReply,QueryRequest,SourceQuery};use serde_json::Value;use std::io;
pub(super) const MAX_ENCODED:u64=64*1024*1024;
pub(super) fn reads_policy(q:&SourceQuery)->bool{matches!(q,SourceQuery::NativeEffectReportBytes{..})}
fn invalid(message:&str)->io::Error{io::Error::new(io::ErrorKind::InvalidData,message)}
pub(super) fn validate_request(request:&QueryRequest)->io::Result<()>{for query in &request.source_queries{if let SourceQuery::NativeEffectReportBytes{environment,configuration,page_width,target_window,cursor,limit}=query{if request.expected_policy_revision.is_none()||!environment.is_absolute()||configuration.as_ref().is_some_and(|p|!p.is_absolute())||!(1..=dm_analysis::checker_effects::MAX_EVENTS as u32).contains(page_width)||!(1..=dm_analysis::checker_effects::MAX_EVENTS as u32).contains(target_window)||*limit==0||*limit as usize>MAX_FRAGMENT{return Err(io::Error::new(io::ErrorKind::InvalidInput,"effect bytes require actual policy pins, absolute paths and bounded windows/fragments"))}if let Some(cursor)=cursor{cursor.validate(MAX_ENCODED)?;}}}Ok(())}
pub(super) fn cursor(row:&Value,key:&str)->io::Result<Option<ByteCursor>>{serde_json::from_value(row[key].clone()).map_err(io::Error::other)}
pub(super) fn validate_requested(reply:&QueryReply,questions:&[SourceQuery])->io::Result<()>{let mut expected=questions.iter().filter(|q|reads_policy(q));for line in reply.jsonl.lines(){let row:Value=serde_json::from_str(line).map_err(io::Error::other)?;if row["row"]!="source_native_effect_report_bytes"{continue}let Some(SourceQuery::NativeEffectReportBytes{environment,configuration,page_width,target_window,cursor:requested,limit})=expected.next()else{return Err(invalid("extra effect byte row"))};let keys=["row","schema","semantic_revision","source_revision","policy_revision","environment","configuration","configuration_explicit","page_width","target_window","full_checker_parity","effect_report_only","byte_fragment_only","output_format","requested_cursor","limit","fragment","bytes"];let object=row.as_object().ok_or_else(||invalid("byte row is not object"))?;let selected=dm_analysis::check_configuration::select(environment,configuration.as_deref());if object.len()!=keys.len()||keys.iter().any(|k|!object.contains_key(*k))||row["schema"]!="dm-session-source-query-v1"||row["semantic_revision"].as_str()!=Some(reply.revision.as_str())||reply.source_revision.is_none()||row["source_revision"].as_str()!=reply.source_revision.as_deref()||reply.policy_revision.is_none()||row["policy_revision"].as_str()!=reply.policy_revision.as_deref()||row["environment"]!=serde_json::to_value(environment).map_err(io::Error::other)?||row["configuration"]!=serde_json::to_value(&selected.path).map_err(io::Error::other)?||row["configuration_explicit"]!=selected.explicit||row["page_width"]!=*page_width||row["target_window"]!=*target_window||row["full_checker_parity"]!=false||row["effect_report_only"]!=true||row["byte_fragment_only"]!=true||row["output_format"]!="source_native_effect_reports_jsonl"||row["requested_cursor"]!=serde_json::to_value(requested).map_err(io::Error::other)?||row["limit"]!=*limit{return Err(invalid("byte row source/configuration/request differs"))}
 let fragment:Fragment=serde_json::from_value(row["fragment"].clone()).map_err(io::Error::other)?;let bytes=row["bytes"].as_array().ok_or_else(||invalid("fragment bytes"))?;let offset=requested.map_or(0,|c|c.offset);let end=offset.checked_add(bytes.len()as u64).filter(|n|*n<=fragment.total).ok_or_else(||invalid("fragment extent"))?;if bytes.iter().any(|b|b.as_u64().is_none_or(|b|b>255))||bytes.len()>*limit as usize||fragment.length as usize!=bytes.len()||fragment.total==0||fragment.total>MAX_ENCODED||fragment.offset!=offset||fragment.end_of_output!=(end==fragment.total)||fragment.next!=(end<fragment.total).then_some(ByteCursor{output_id:fragment.output_id,total:fragment.total,offset:end})||!fragment.end_of_output&&bytes.len()!=*limit as usize||requested.is_some_and(|c|c.output_id!=fragment.output_id||c.total!=fragment.total){return Err(invalid("fragment identity/continuity/total differs"))}
 }if expected.next().is_some(){return Err(invalid("missing effect byte row"))}Ok(())}

#[cfg(test)]mod tests{use super::*;#[test]fn byte_request_rejects_unpinned_oversized_and_invalid_continuations(){let root=std::env::current_dir().unwrap();let q=SourceQuery::NativeEffectReportBytes{environment:root.join("project.dme"),configuration:None,page_width:1,target_window:1,cursor:None,limit:MAX_FRAGMENT as u32};let mut request=QueryRequest{timeout_seconds:Some(300),project:root.join("project.dme"),defines:Default::default(),engine_template:None,bootstrap_catalog:false,expected_revision:Some("1".repeat(32)),expected_source_revision:Some("2".repeat(32)),expected_policy_revision:Some("3".repeat(32)),queries:vec![],source_queries:vec![q]};request.validate().unwrap();request.expected_policy_revision=None;assert!(request.validate().is_err());request.expected_policy_revision=Some("3".repeat(32));if let SourceQuery::NativeEffectReportBytes{limit,..}=&mut request.source_queries[0]{*limit=MAX_FRAGMENT as u32+1;}assert!(request.validate().is_err());if let SourceQuery::NativeEffectReportBytes{limit,cursor,..}=&mut request.source_queries[0]{*limit=1;*cursor=Some(ByteCursor{output_id:super::super::encoded_bytes::OutputId(1),total:2,offset:2});}assert!(request.validate().is_err());}}
